mapper.select:
select a.id as account_id, a.tenant_id, a.username, a.display_name, a.password_hash,
       a.authorities_csv, a.enabled, a.must_change_password
  from batch.console_external_identity i
  join batch.console_user_account a
    on a.tenant_id = i.tenant_id and a.id = i.account_id
 where i.tenant_id = #{tenantId}
   and i.issuer = #{issuer}
   and i.subject = #{subject}
   and a.enabled = true
 limit 1
